  for (let i = 0; i < 1_200; i += 1) queue.enqueue('x', { i, padding });
  assert.ok(fs.statSync(log).size > 3 * 1024 * 1024);
  fs.truncateSync(log, fs.statSync(log).size - 100);
  const reopened = open();
  assert.equal(reopened.stats().total, 1_199);
});

