test('retry times, attempts and tokens survive restart and compaction', (t) => {
  const { open, clock } = setup(t);
  const queue = open();
  const { id } = queue.enqueue('x', null, { maxAttempts: 3 });
  let job = queue.claim('w');
  const { retryAt } = queue.fail(id, job.token, 'one');
  clock.advance(10_000_000);
  const reopened = open();
  assert.equal(reopened.getJob(id).availableAt, retryAt);
  reopened.compact();
  const again = open();
  assert.equal(again.getJob(id).availableAt, retryAt);
  assert.equal(again.getJob(id).attempts, 1);
  job = again.claim('w');
  assert.equal(job.attempt, 2);
  assert.equal(job.token, 2);
  again.fail(id, job.token, 'two');
  clock.advance(10_000);
  again.compact();
  job = open().claim('w');
  assert.equal(job.attempt, 3);
  assert.equal(open().fail(id, job.token, 'three').status, 'dead');
});

