test('a key is still remembered after its job was pruned and the log compacted', (t) => {
  const { open, clock } = setup(t, { retainCompletedMs: 1_000 });
  const queue = open();
  const first = queue.enqueue('report', 1, { key: 'monthly' });
  const job = queue.claim('w');
  queue.complete(job.id, job.token, { sent: true });
  clock.advance(60_000);
  queue.compact();
  assert.equal(queue.getJob(first.id), null);
  for (const q of [queue, open()]) {
    const again = q.enqueue('report', 2, { key: 'monthly' });
    assert.equal(again.deduped, true);
    assert.equal(again.id, first.id);
    assert.deepEqual(again.result, { sent: true });
  }
  queue.compact();
  const third = open().enqueue('report', 3, { key: 'monthly' });
  assert.equal(third.deduped, true);
  clock.advance(7 * 24 * 3_600_000);
  assert.equal(open().enqueue('report', 4, { key: 'monthly' }).deduped, false);
});

