  assert.deepEqual(receipt, {
    id,
    outcome: 'committed',
    token: job.token,
    result: { a: 1 },
    completedAt: 1_005,
    completionSeq: 1,
  });
  const size = fs.statSync(path.join(queue.dir, 'wal.log')).size;
  clock.advance(500);
  const again = queue.complete(id, job.token, { a: 'ignored' });
  assert.deepEqual(again, { ...receipt, outcome: 'already-committed' });
  assert.equal(fs.statSync(path.join(queue.dir, 'wal.log')).size, size);
  queue.compact();
  assert.deepEqual(open().complete(id, job.token, 'ignored'), { ...receipt, outcome: 'already-committed' });
  assert.throws(() => queue.complete(id, job.token + 1, 'x'), StaleLeaseError);
  assert.throws(() => queue.complete('nope', 1, 'x'), UnknownJobError);
});

