// The crash table: commit point is the durable complete record.

const CRASH_TABLE = [
  ['wal.before-append', 'complete', true],
  ['wal.mid-append', 'complete', true],
  ['wal.after-write', 'complete', true],
  ['wal.after-fsync', 'complete', false],
];

for (const [point, type, reruns] of CRASH_TABLE) {
  test(`a crash at ${point} while completing ${reruns ? 'runs the job again' : 'does not'}`, (t) => {
    const { open, clock } = setup(t);
    const queue = open();
    const { id } = queue.enqueue('x', null);
    const job = queue.claim('w', { leaseMs: 100 });
    crashAt(point, () => queue.complete(id, job.token, 'r'), type);
    const after = open();
    if (reruns) {
      assert.equal(after.getJob(id).status, 'leased');
      clock.advance(100);
      after.reapExpired();
      clock.advance(10_000);
      assert.equal(after.claim('w2').id, id);
    } else {
      assert.equal(after.getJob(id).status, 'done');
      clock.advance(10_000);
      assert.equal(after.reapExpired().length, 0);
      assert.equal(after.claim('w2'), null);
      assert.equal(after.complete(id, job.token, 'x').outcome, 'already-committed');
    }
  });
}

