import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import {
  clearFailpoints,
  CorruptLogError,
  ManualClock,
  onFailpoint,
  openQueue,
  StaleLeaseError,
  UnknownJobError,
} from '../src/index.mjs';
import { defer, tempDir } from './helpers/tmp.mjs';

class Crash extends Error {}

// Power-loss model on, and a throwing failpoint standing in for a kill. The
// queue object that "died" is dropped, taking its unsynced bytes with it.
function powerLoss(t) {
  const before = process.env.WALQ_SIMULATE_POWER_LOSS;
  process.env.WALQ_SIMULATE_POWER_LOSS = '1';
  defer(t, () => {
    clearFailpoints();
    if (before === undefined) delete process.env.WALQ_SIMULATE_POWER_LOSS;
    else process.env.WALQ_SIMULATE_POWER_LOSS = before;
  });
}

function crashAt(point, fn, type = null) {
  const off = onFailpoint(point, (ctx) => {
    if (type === null || ctx.type === type) throw new Crash(point);
  });
  try {
    assert.throws(fn, Crash);
  } finally {
    off();
  }
}

const OPTIONS = { backoff: { baseMs: 100, factor: 2, maxMs: 10_000 } };

function setup(t, extra = {}) {
  powerLoss(t);
  const clock = new ManualClock(1_000);
  const dir = tempDir(t);
  const open = (more = {}) => openQueue(dir, { clock, ...OPTIONS, ...extra, ...more });
  return { clock, dir, open, log: path.join(dir, 'wal.log') };
}

const WAL_POINTS = ['wal.before-append', 'wal.mid-append', 'wal.after-write'];

for (const point of WAL_POINTS) {
  test(`a crash at ${point} leaves a log that opens, and later writes survive`, (t) => {
    const { open, log } = setup(t);
    const queue = open();
    queue.enqueue('x', 'first');
    crashAt(point, () => queue.enqueue('x', 'lost'));
    const reopened = open();
    assert.deepEqual(reopened.listJobs().map((j) => j.payload), ['first']);
    reopened.enqueue('x', 'after');
    const third = open();
    assert.deepEqual(third.listJobs().map((j) => j.payload), ['first', 'after']);
    assert.ok(fs.statSync(log).size > 0);
  });
}

