    completedAt: 1_002,
    completionSeq: 2,
  });
  assert.deepEqual(queue.completions().map((c) => c.seq), [1, 2, 3]);
  assert.deepEqual(queue.completions({ after: 1, limit: 1 }).map((c) => c.id), [ids[1]]);
  clock.advance(1_001);
  queue.compact();
  const next = queue.enqueue('x', 'd');
  const job = queue.claim('w');
  queue.complete(next.id, job.token, 'r');
  assert.deepEqual(open().completions({ after: 0 }).map((c) => c.seq), [4]);
