test('reclaimWorker frees only that worker\'s jobs, at once, without backoff', (t) => {
  const { open } = setup(t);
  const queue = open();
  const [a, b, c] = ['a', 'b', 'c'].map((p) => queue.enqueue('x', p).id);
  const ja = queue.claim('dead');
  const jb = queue.claim('alive');
  const jc = queue.claim('dead');
  queue.complete(jc.id, jc.token, 'done already');
  assert.deepEqual(queue.reclaimWorker('dead', { reason: 'power' }), [{ id: a, status: 'ready' }]);
  assert.equal(queue.getJob(a).lastError, 'power');
  assert.equal(queue.getJob(b).status, 'leased');
  assert.equal(queue.getJob(c).status, 'done');
  assert.throws(() => queue.complete(a, ja.token, 'x'), StaleLeaseError);
  const again = queue.claim('w2');
  assert.equal(again.id, a);
  assert.equal(again.attempt, 2);
  assert.deepEqual(queue.reclaimWorker('nobody'), []);
  assert.ok(jb);
});

test('reclaimWorker sends a job out of attempts to dead', (t) => {
  const { open } = setup(t);
  const queue = open();
  const { id } = queue.enqueue('x', null, { maxAttempts: 1 });
  queue.claim('w');
  assert.deepEqual(queue.reclaimWorker('w'), [{ id, status: 'dead' }]);
  assert.equal(queue.getJob(id).status, 'dead');
});

// The crash table: commit point is the durable complete record.

const CRASH_TABLE = [
  ['wal.before-append', 'complete', true],
  ['wal.mid-append', 'complete', true],
  ['wal.after-write', 'complete', true],
  ['wal.after-fsync', 'complete', false],
];

for (const [point, type, reruns] of CRASH_TABLE) {
  test(`a crash at ${point} while completing ${reruns ? 'runs the job again' : 'does not'}`, (t) => {
    const { open, clock } = setup(t);
    const queue = open();
    const { id } = queue.enqueue('x', null);
    const job = queue.claim('w', { leaseMs: 100 });
    crashAt(point, () => queue.complete(id, job.token, 'r'), type);
    const after = open();
    if (reruns) {
      assert.equal(after.getJob(id).status, 'leased');
      clock.advance(100);
      after.reapExpired();
      clock.advance(10_000);
      assert.equal(after.claim('w2').id, id);
    } else {
      assert.equal(after.getJob(id).status, 'done');
      clock.advance(10_000);
      assert.equal(after.reapExpired().length, 0);
      assert.equal(after.claim('w2'), null);
      assert.equal(after.complete(id, job.token, 'x').outcome, 'already-committed');
    }
  });
}

test('a compaction killed while a completion is the newest record loses nothing', (t) => {
  for (const point of ['compact.after-tmp-write', 'compact.before-rename', 'compact.after-rename']) {
    const { open, clock } = setup(t);
    const queue = open();
    const { id } = queue.enqueue('x', null);
    const job = queue.claim('w');
    queue.complete(id, job.token, 'r');
    crashAt(point, () => queue.compact());
    clock.advance(1_000_000);
    const after = open();
    assert.equal(after.getJob(id).status, 'done');
    assert.equal(after.claim('w2'), null);
  }
});
