import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { ManualClock, openQueue, StaleLeaseError } from '../src/index.mjs';

let seed = Number(process.argv[2] ?? 1);
const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 2 ** 32; };
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'walq-fuzz-'));
const clock = new ManualClock(1_000);
const opts = { clock, compactAfterBytes: 1_500, retainCompletedMs: 5_000, idempotencyTtlMs: 30_000, backoff: { baseMs: 10, factor: 2, maxMs: 100, jitter: 0.3 } };
let qs = [0, 1, 2].map(() => openQueue(dir, opts));
const held = new Map();
const tokens = new Map();
const commits = new Map();
const keyJob = new Map();
let enq = 0;
for (let step = 0; step < 4000; step += 1) {
  const q = qs[Math.floor(rnd() * qs.length)];
  const r = rnd();
  clock.advance(Math.floor(rnd() * 40));
  if (r < 0.2) {
    const key = rnd() < 0.5 ? `k${Math.floor(rnd() * 30)}` : undefined;
    const out = q.enqueue('x', { n: enq += 1, pad: 'p'.repeat(30) }, { key, maxAttempts: 4 });
    if (key) {
      const known = keyJob.get(key);
      if (known && clock.now() - known.at < 30_000) assert.equal(out.id, known.id, `key ${key} gave a new job`);
      else keyJob.set(key, { id: out.id, at: clock.now() });
    }
  } else if (r < 0.45) {
    const job = q.claim(`w${Math.floor(rnd() * 3)}`, { leaseMs: 200 });
    if (job) {
      const seen = tokens.get(job.id) ?? new Set();
      assert.ok(!seen.has(job.token), `token ${job.token} reissued for ${job.id}`);
      seen.add(job.token); tokens.set(job.id, seen);
      assert.ok(!commits.has(job.id), `${job.id} claimed after commit`);
      assert.ok(job.attempt <= 4, `${job.id} attempt ${job.attempt}`);
      held.set(`${job.id}`, job);
    }
  } else if (r < 0.65 && held.size) {
    const [id, job] = [...held][Math.floor(rnd() * held.size)];
    try {
      const out = q.complete(id, job.token, 'r');
      if (out.outcome === 'committed') { assert.ok(!commits.has(id)); commits.set(id, out.completionSeq); }
      held.delete(id);
    } catch (e) { if (!(e instanceof StaleLeaseError)) throw e; held.delete(id); }
  } else if (r < 0.75 && held.size) {
    const [id, job] = [...held][Math.floor(rnd() * held.size)];
    try { q.fail(id, job.token, 'boom'); } catch (e) { if (!(e instanceof StaleLeaseError)) throw e; }
    held.delete(id);
  } else if (r < 0.82 && held.size) {
    const [id, job] = [...held][Math.floor(rnd() * held.size)];
    try { q.heartbeat(id, job.token, { leaseMs: 200 }); } catch (e) { if (!(e instanceof StaleLeaseError)) throw e; held.delete(id); }
  } else if (r < 0.9) q.reapExpired();
  else if (r < 0.93) q.compact();
  else if (r < 0.96) { qs[qs.indexOf(q)] = openQueue(dir, opts); }
  else q.reclaimWorker(`w${Math.floor(rnd() * 3)}`);
}
const views = qs.map((q) => JSON.stringify(q.listJobs()));
assert.ok(views.every((v) => v === views[0]), 'processes disagree');
assert.equal(JSON.stringify(openQueue(dir, opts).listJobs()), views[0], 'fresh open differs');
const seqs = qs[0].completions().map((c) => c.seq);
assert.deepEqual(seqs, [...seqs].sort((a, b) => a - b));
console.log('ok', process.argv[2], 'jobs', qs[0].stats().total, 'gen', qs[0].stats().generation, 'commits', commits.size);
fs.rmSync(dir, { recursive: true, force: true });
